import { data, TakaroUserError } from '@takaro/helpers';
import {
  cfg,
  getTexts,
  getSetting,
  chatWords,
  findGame,
  enabledGames,
  getOnlinePlayers,
  pickByName,
  findGameOf,
  takeStake,
  addCurrency,
  createGame,
  pmGameId,
  newBoard,
} from './cbg-helpers.js';

async function main() {
  const { player, pog, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const { prefix, currency } = await getTexts(gameServerId);
  const games = enabledGames(c);
  if (games.length === 0) throw new TakaroUserError('No board games are enabled on this server.');
  const gameList = games.map((g) => g.aliases[0]).join(', ');
  const usage = `Usage: ${prefix}challenge <player> <${games.map((g) => g.aliases[0]).join('|')}> [bet]`;

  // Read the full chat line: names can have spaces and Takaro passes text args as one word.
  const words = chatWords();
  let bet = 0;
  if (words.length > 1 && /^\d+$/.test(words[words.length - 1])) bet = Number(words.pop());

  let game = null;
  const gameIdx = words.findIndex((w) => findGame(w));
  if (gameIdx >= 0) {
    game = findGame(words[gameIdx]);
    words.splice(gameIdx, 1);
  } else if (games.length === 1) {
    game = games[0];
  }
  const targetName = words.join(' ');
  if (!game || !targetName) throw new TakaroUserError(usage);
  if (!c.enabled[game.id]) throw new TakaroUserError(`${game.name} is turned off here. Games: ${gameList}.`);

  if (bet > 0) {
    const economy = String(await getSetting('economyEnabled', gameServerId, 'true'));
    if (economy === 'false') throw new TakaroUserError('Bets need the economy, which is turned off. Play without a bet.');
    if (c.maxBet <= 0) throw new TakaroUserError('Bets are turned off on this server. Play without a bet.');
    if (bet < c.minBet) throw new TakaroUserError(`The minimum bet is ${c.minBet} ${currency}.`);
    if (bet > c.maxBet) throw new TakaroUserError(`The maximum bet is ${c.maxBet} ${currency}.`);
    if ((Number(pog.currency) || 0) < bet) throw new TakaroUserError(`You do not have ${bet} ${currency}.`);
  }

  const online = await getOnlinePlayers(gameServerId);
  const target = pickByName(online, targetName, 'online player');
  if (target.id === player.id) throw new TakaroUserError('You cannot challenge yourself.');

  const [mine, theirs] = [
    await findGameOf(gameServerId, mod.moduleId, player.id),
    await findGameOf(gameServerId, mod.moduleId, target.id),
  ];
  if (mine) {
    throw new TakaroUserError(
      mine.game.status === 'pending'
        ? `You already have an open challenge. Withdraw it with ${prefix}forfeit.`
        : `You are already in a game. See it with ${prefix}board or give up with ${prefix}forfeit.`,
    );
  }
  if (theirs) throw new TakaroUserError(`${target.name} is already in a game. Try again later.`);

  if (!(await takeStake(gameServerId, player.id, bet))) throw new TakaroUserError(`You do not have ${bet} ${currency}.`);

  const now = new Date().toISOString();
  const row = {
    id: `${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`,
    game: game.id,
    status: 'pending',
    bet,
    challengerId: player.id,
    challengerName: player.name,
    challengerGameId: pog.gameId,
    opponentId: target.id,
    opponentName: target.name,
    opponentGameId: target.gameId,
    createdAt: now,
    lastMoveAt: now,
    board: newBoard(game.id),
  };
  try {
    await createGame(gameServerId, mod.moduleId, row);
  } catch (err) {
    await addCurrency(gameServerId, player.id, bet);
    console.log(`chat-board-games: could not store challenge: ${err}`);
    throw new TakaroUserError('Could not create the challenge. Your stake was refunded. Please try again.');
  }

  const betText = bet > 0 ? ` for ${bet} ${currency} each (winner takes ${bet * 2})` : '';
  const mins = c.challengeTimeoutMinutes;
  await data.player.pm(`You challenged ${target.name} to ${game.name}${betText}. They have ${mins} min to accept.`);
  await pmGameId(gameServerId, target.gameId, `${player.name} challenges you to ${game.name}${betText}.`);
  await pmGameId(gameServerId, target.gameId, `Type ${prefix}accept or ${prefix}decline within ${mins} min.`);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import {
  cfg,
  getTexts,
  findGameOf,
  takeStake,
  addCurrency,
  saveGame,
  pmGameId,
  announceTurn,
  gameName,
  potText,
  moveHint,
} from './cbg-helpers.js';

async function main() {
  const { player, pog, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const { prefix, currency } = await getTexts(gameServerId);

  const found = await findGameOf(gameServerId, mod.moduleId, player.id);
  if (!found || found.game.status !== 'pending' || found.game.opponentId !== player.id) {
    if (found && found.game.status === 'active') throw new TakaroUserError(`You are already in a game. See it with ${prefix}board.`);
    throw new TakaroUserError('You have no open challenge to accept.');
  }
  const { variable, game } = found;
  const bet = Number(game.bet) || 0;
  if (bet > 0 && (Number(pog.currency) || 0) < bet) {
    throw new TakaroUserError(`You need ${bet} ${currency} to accept. Type ${prefix}decline to refuse.`);
  }
  if (!(await takeStake(gameServerId, player.id, bet))) {
    throw new TakaroUserError(`You need ${bet} ${currency} to accept. Type ${prefix}decline to refuse.`);
  }

  // Random first player; the starter plays X.
  const challengerStarts = Math.random() < 0.5;
  game.status = 'active';
  game.challengerMark = challengerStarts ? 'X' : 'O';
  game.turn = 'X';
  game.round = 1;
  game.score = { X: 0, O: 0 };
  game.acceptedAt = new Date().toISOString();
  game.lastMoveAt = game.acceptedAt;
  if (!(await saveGame(variable, game))) {
    await addCurrency(gameServerId, player.id, bet);
    throw new TakaroUserError('That challenge just expired.');
  }

  const xName = challengerStarts ? game.challengerName : game.opponentName;
  const oName = challengerStarts ? game.opponentName : game.challengerName;
  const name = gameName(game);
  if (game.game === 'rps') {
    const bo = c.rpsBestOf > 1 ? ` Best of ${c.rpsBestOf}.` : '';
    const line = `Game on: ${name}, ${game.challengerName} vs ${game.opponentName}.${potText(game, currency)}${bo}`;
    for (const gid of [game.challengerGameId, game.opponentGameId]) {
      await pmGameId(gameServerId, gid, line);
      await pmGameId(gameServerId, gid, `Pick in secret: ${moveHint(game, prefix)}`);
    }
    return;
  }
  const line = `Game on: ${name}, ${xName} (X) vs ${oName} (O).${potText(game, currency)} X starts.`;
  await pmGameId(gameServerId, game.challengerGameId, line);
  await pmGameId(gameServerId, game.opponentGameId, line);
  await announceTurn(gameServerId, game, prefix);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { getTexts, findGameOf, claimEnd, finishGame } from './cbg-helpers.js';

async function main() {
  const { player, gameServerId, module: mod } = data;
  const texts = await getTexts(gameServerId);

  const found = await findGameOf(gameServerId, mod.moduleId, player.id);
  if (!found || found.game.status !== 'pending' || found.game.opponentId !== player.id) {
    throw new TakaroUserError('You have no open challenge to decline.');
  }
  const { variable, game } = found;
  if (!(await claimEnd(variable))) throw new TakaroUserError('That challenge is already gone.');
  await finishGame(gameServerId, mod, game, {
    refund: true,
    messages: {
      challenger: `${game.opponentName} declined your challenge.`,
      opponent: `You declined the challenge from ${game.challengerName}.`,
    },
  }, texts);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import {
  cfg,
  getTexts,
  chatWords,
  findGameOf,
  saveGame,
  claimEnd,
  finishGame,
  side,
  applyMove,
  boardResult,
  playerByMark,
  announceTurn,
  pmGameId,
  moveHint,
  parseRpsPick,
  rpsCompare,
  getRpsPick,
  setRpsPick,
} from './cbg-helpers.js';

async function playRps(game, variable, me, texts) {
  const { player, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const { prefix } = texts;
  const pick = parseRpsPick(chatWords()[0]);
  if (!pick) throw new TakaroUserError(`Pick one: ${moveHint(game, prefix)}`);

  const mine = await getRpsPick(gameServerId, mod.moduleId, player.id, game.id);
  if (mine && mine.pick.round === game.round) throw new TakaroUserError(`You already picked ${mine.pick.pick} this round.`);
  await setRpsPick(gameServerId, mod.moduleId, player.id, game.id, game.round, pick);

  const theirs = await getRpsPick(gameServerId, mod.moduleId, me.other.id, game.id);
  if (!theirs || theirs.pick.round !== game.round) {
    await player.pm(`You picked ${pick}. Waiting for ${me.other.name}.`);
    await pmGameId(gameServerId, me.other.gameId, `${player.name} has picked. Your pick: ${moveHint(game, prefix)}`);
    return;
  }

  const otherPick = theirs.pick.pick;
  const res = rpsCompare(pick, otherPick);
  const reveal = `${player.name}: ${pick}, ${me.other.name}: ${otherPick}.`;
  const myGameId = data.pog.gameId;
  const otherMark = me.mark === 'X' ? 'O' : 'X';
  game.score = game.score ?? { X: 0, O: 0 };

  if (res === 0) {
    game.round += 1;
    game.lastMoveAt = new Date().toISOString();
    if (!(await saveGame(variable, game))) throw new TakaroUserError('That game already ended.');
    for (const gid of [myGameId, me.other.gameId]) {
      await pmGameId(gameServerId, gid, `${reveal} Same pick, no point.`);
      await pmGameId(gameServerId, gid, `Pick again: ${moveHint(game, prefix)}`);
    }
    return;
  }

  const roundWinnerMark = res > 0 ? me.mark : otherMark;
  game.score[roundWinnerMark] = (game.score[roundWinnerMark] ?? 0) + 1;
  const need = Math.floor(Math.max(1, c.rpsBestOf) / 2) + 1;
  const roundWinner = res > 0 ? player.name : me.other.name;
  if (game.score[roundWinnerMark] >= need) {
    for (const gid of [myGameId, me.other.gameId]) await pmGameId(gameServerId, gid, reveal);
    if (!(await claimEnd(variable))) return;
    const winnerId = res > 0 ? player.id : me.other.id;
    await finishGame(gameServerId, mod, game, { winnerId, reason: need > 1 ? `${game.score[roundWinnerMark]}-${game.score[roundWinnerMark === 'X' ? 'O' : 'X']}` : `${res > 0 ? pick : otherPick} beats ${res > 0 ? otherPick : pick}` }, texts);
    return;
  }
  game.round += 1;
  game.lastMoveAt = new Date().toISOString();
  if (!(await saveGame(variable, game))) throw new TakaroUserError('That game already ended.');
  const myScore = game.score[me.mark];
  const theirScore = game.score[otherMark];
  await pmGameId(gameServerId, myGameId, `${reveal} ${roundWinner} wins the round. Score: you ${myScore}, ${me.other.name} ${theirScore}.`);
  await pmGameId(gameServerId, me.other.gameId, `${reveal} ${roundWinner} wins the round. Score: you ${theirScore}, ${player.name} ${myScore}.`);
  for (const gid of [myGameId, me.other.gameId]) await pmGameId(gameServerId, gid, `Next round: ${moveHint(game, prefix)}`);
}

async function main() {
  const { player, gameServerId, module: mod } = data;
  const texts = await getTexts(gameServerId);
  const { prefix } = texts;

  const found = await findGameOf(gameServerId, mod.moduleId, player.id);
  if (!found) throw new TakaroUserError(`You are not in a game. Start one with ${prefix}challenge <player> <game> [bet].`);
  const { variable, game } = found;
  if (game.status !== 'active') {
    throw new TakaroUserError(
      game.opponentId === player.id ? `Accept the challenge first with ${prefix}accept.` : `Waiting for ${game.opponentName} to accept.`,
    );
  }
  const me = side(game, player.id);
  if (game.game === 'rps') {
    await playRps(game, variable, me, texts);
    return;
  }

  if (game.turn !== me.mark) throw new TakaroUserError(`It is ${me.other.name}'s turn. You are ${me.mark}.`);
  const word = chatWords()[0];
  if (!word) throw new TakaroUserError(`Usage: ${moveHint(game, prefix)}`);
  const err = applyMove(game, me.mark, word);
  if (err) throw new TakaroUserError(err);

  const result = boardResult(game);
  if (result) {
    if (!(await claimEnd(variable))) throw new TakaroUserError('That game already ended.');
    if (result === 'draw') {
      await finishGame(gameServerId, mod, game, { draw: true }, texts);
    } else {
      await finishGame(gameServerId, mod, game, { winnerId: playerByMark(game, result).id }, texts);
    }
    return;
  }

  game.turn = me.mark === 'X' ? 'O' : 'X';
  game.lastMoveAt = new Date().toISOString();
  if (!(await saveGame(variable, game))) throw new TakaroUserError('That game already ended.');
  await pmGameId(gameServerId, me.other.gameId, `${player.name} played ${game.lastMove}.`);
  await announceTurn(gameServerId, game, prefix);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { cfg, getTexts, findGameOf, sendBoard, side, gameName, potText, moveHint, getRpsPick, minutesSince } from './cbg-helpers.js';

async function main() {
  const { player, pog, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const { prefix, currency } = await getTexts(gameServerId);

  const found = await findGameOf(gameServerId, mod.moduleId, player.id);
  if (!found) throw new TakaroUserError(`You are not in a game. Start one with ${prefix}challenge <player> <game> [bet].`);
  const { game } = found;
  const { mark, other } = side(game, player.id);
  const name = gameName(game);

  if (game.status === 'pending') {
    const left = Math.max(0, Math.ceil(c.challengeTimeoutMinutes - minutesSince(game.createdAt)));
    const text = game.challengerId === player.id
      ? `Your ${name} challenge to ${other.name} is waiting (${left} min left).${potText(game, currency)}`
      : `${other.name} challenged you to ${name}.${potText(game, currency)} Type ${prefix}accept or ${prefix}decline (${left} min left).`;
    await player.pm(text);
    return;
  }

  const left = Math.max(0, Math.ceil(c.turnTimeoutMinutes - minutesSince(game.lastMoveAt)));
  if (game.game === 'rps') {
    const mine = await getRpsPick(gameServerId, mod.moduleId, player.id, game.id);
    const picked = mine && mine.pick.round === game.round ? `You picked ${mine.pick.pick}.` : `Your pick: ${moveHint(game, prefix)}`;
    const myScore = game.score?.[mark] ?? 0;
    const theirScore = game.score?.[mark === 'X' ? 'O' : 'X'] ?? 0;
    await player.pm(`${name} vs ${other.name}, round ${game.round}, score ${myScore}-${theirScore}.${potText(game, currency)}`);
    await player.pm(`${picked} ${left} min left.`);
    return;
  }
  const status = game.turn === mark
    ? `Your turn (${mark}) vs ${other.name}: ${moveHint(game, prefix)} (${left} min left)`
    : `Waiting for ${other.name}. You are ${mark}.`;
  await player.pm(`${name} vs ${other.name}.${potText(game, currency)}`);
  await sendBoard(gameServerId, game, pog.gameId, status);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { getTexts, findGameOf, claimEnd, finishGame, side } from './cbg-helpers.js';

async function main() {
  const { player, gameServerId, module: mod } = data;
  const texts = await getTexts(gameServerId);

  const found = await findGameOf(gameServerId, mod.moduleId, player.id);
  if (!found) throw new TakaroUserError('You are not in a game.');
  const { variable, game } = found;
  if (!(await claimEnd(variable))) throw new TakaroUserError('That game already ended.');

  if (game.status === 'pending') {
    // Withdrawing your own challenge, or refusing one aimed at you: nobody loses, the stake comes back.
    const mine = game.challengerId === player.id;
    await finishGame(gameServerId, mod, game, {
      refund: true,
      messages: mine
        ? { challenger: `You withdrew your challenge to ${game.opponentName}.`, opponent: `${game.challengerName} withdrew the challenge.` }
        : { challenger: `${game.opponentName} declined your challenge.`, opponent: `You declined the challenge from ${game.challengerName}.` },
    }, texts);
    return;
  }
  const { other } = side(game, player.id);
  await finishGame(gameServerId, mod, game, { winnerId: other.id, reason: `${player.name} forfeited` }, texts);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { getTexts, chatWords, listStats, getStats, pickByName, GAMES } from './cbg-helpers.js';

function record(s) {
  return `${s.wins ?? 0} wins, ${s.losses ?? 0} losses, ${s.draws ?? 0} draws`;
}

async function main() {
  const { player, gameServerId, module: mod } = data;
  const { prefix, currency } = await getTexts(gameServerId);
  const name = chatWords().join(' ');

  let stats;
  let who;
  if (name) {
    const all = await listStats(gameServerId, mod.moduleId);
    const hit = pickByName(all.map((r) => ({ ...r, name: r.stats.name })), name, 'player with board game stats');
    stats = hit.stats;
    who = hit.stats.name;
  } else {
    const mine = await getStats(gameServerId, mod.moduleId, player.id);
    if (!mine) throw new TakaroUserError(`You have not finished a board game yet. Try ${prefix}challenge <player> <game> [bet].`);
    stats = mine.stats;
    who = 'You';
  }
  const net = Number(stats.net) || 0;
  await player.pm(`${who}: ${record(stats)}. Bets: ${net >= 0 ? '+' : ''}${net} ${currency}.`);
  for (const g of Object.values(GAMES)) {
    const s = stats.games?.[g.id];
    if (s) await player.pm(`${g.name}: ${record(s)}`);
  }
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { cfg, getTexts, chatWords, listStats, findGame } from './cbg-helpers.js';

async function main() {
  const { player, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const { prefix } = await getTexts(gameServerId);
  const word = chatWords()[0];
  const game = word ? findGame(word) : null;
  if (word && !game) throw new TakaroUserError(`Unknown game "${word}". Use ttt, c4 or rps, or nothing for all games.`);

  const rows = (await listStats(gameServerId, mod.moduleId))
    .map(({ stats }) => {
      const s = game ? stats.games?.[game.id] : stats;
      return s ? { name: stats.name, wins: s.wins ?? 0, losses: s.losses ?? 0, draws: s.draws ?? 0 } : null;
    })
    .filter((r) => r && r.wins + r.losses + r.draws > 0)
    .sort((a, b) => b.wins - a.wins || a.losses - b.losses || a.name.localeCompare(b.name))
    .slice(0, Math.max(1, c.leaderboardSize));

  if (rows.length === 0) {
    await player.pm(`No finished games yet. Be the first: ${prefix}challenge <player> <game> [bet]`);
    return;
  }
  await player.pm(`Board games top ${rows.length}${game ? ` (${game.name})` : ''}:`);
  for (const [i, r] of rows.entries()) {
    await player.pm(`${i + 1}. ${r.name} - ${r.wins} wins, ${r.losses} losses, ${r.draws} draws`);
  }
}

await main();

import { data, TakaroUserError, checkPermission } from '@takaro/helpers';
import {
  cfg,
  getTexts,
  chatWords,
  enabledGames,
  listGames,
  pickByName,
  claimEnd,
  finishGame,
  gameName,
  potText,
} from './cbg-helpers.js';

async function main() {
  const { player, pog, gameServerId, module: mod } = data;
  const c = cfg(mod.userConfig);
  const texts = await getTexts(gameServerId);
  const { prefix, currency } = texts;
  const [action, ...rest] = chatWords();
  const act = String(action ?? '').toLowerCase();

  if (!act || act === 'help') {
    const games = enabledGames(c).map((g) => `${g.aliases[0]} (${g.name})`).join(', ');
    await player.pm(`Board games: ${games || 'none enabled'}.`);
    await player.pm(`${prefix}challenge <player> <game> [bet] - challenge someone, bet is optional.`);
    await player.pm(`${prefix}accept or ${prefix}decline - answer a challenge.`);
    await player.pm(`${prefix}move <square|column|rock|paper|scissors> - play. ${prefix}board shows the game.`);
    await player.pm(`${prefix}forfeit - give up or withdraw. ${prefix}gamestats and ${prefix}gametop - stats.`);
    if (c.maxBet > 0) await player.pm(`Bets are held until the game ends (max ${c.maxBet} ${currency}). Expired or declined challenges are refunded.`);
    return;
  }

  if (act !== 'list' && act !== 'cancel') throw new TakaroUserError(`Unknown option "${action}". Use ${prefix}boardgames, list or cancel <player>.`);
  if (!checkPermission(pog, 'BOARD_GAMES_MANAGE')) throw new TakaroUserError('You do not have permission to manage board games.');

  const games = await listGames(gameServerId, mod.moduleId);
  if (act === 'list') {
    if (games.length === 0) {
      await player.pm('No board games are running.');
      return;
    }
    await player.pm(`${games.length} board game${games.length === 1 ? '' : 's'}:`);
    for (const { game } of games) {
      await player.pm(`${game.challengerName} vs ${game.opponentName}: ${gameName(game)}, ${game.status}.${potText(game, currency)}`);
    }
    return;
  }

  const name = rest.join(' ');
  if (!name) throw new TakaroUserError(`Usage: ${prefix}boardgames cancel <player>`);
  const candidates = games.flatMap(({ variable, game }) => [
    { name: game.challengerName, variable, game },
    { name: game.opponentName, variable, game },
  ]);
  const hit = pickByName(candidates, name, 'player in a board game');
  if (!(await claimEnd(hit.variable))) throw new TakaroUserError('That game already ended.');
  const text = `An admin cancelled your ${gameName(hit.game)} game.`;
  await finishGame(gameServerId, mod, hit.game, { refund: true, messages: { challenger: text, opponent: text } }, texts);
  await player.pm(`Cancelled ${hit.game.challengerName} vs ${hit.game.opponentName}. Stakes refunded.`);
}

await main();

